"""runtime.commands: generated by the graph.py split (P1)."""

from __future__ import annotations

import os
import shlex
from pathlib import Path

from ..benchmark import embench
from ..benchmark.embench import DEFAULT_MARCH
from ..flow import gates
from ..runtime import tools
from ..runtime.tools import DESIGN_WORKSPACE_SUBDIR, RepoToolbox, SOC_WORKSPACE_SUBDIR
from ..state import CfuDesignState


def _missing_design_files(state: CfuDesignState) -> list[str]:
    """Overlay hardware files that are absent or empty (agent-CFU runs only)."""
    run_root = state.get("run_root", "")
    if not run_root or not gates.is_agent_cfu_run(state):
        return []
    workdir = Path(state.get("workdir", ".")).resolve()
    missing: list[str] = []
    for overlay in tools.design_workspace_paths(run_root).values():
        path = workdir / overlay
        if not path.is_file() or not path.read_text(errors="replace").strip():
            missing.append(overlay)
    return missing


def _soc_rtl_path(state: CfuDesignState) -> Path | None:
    run_root = state.get("run_root", "")
    if not run_root:
        return None
    return Path(state.get("workdir", ".")).resolve() / run_root / SOC_WORKSPACE_SUBDIR / "MiCoSoc.v"


def _legacy_ladder_commands(
    state: CfuDesignState,
    toolbox: RepoToolbox,
) -> dict[str, list[list[str]]]:
    """Split the non-embench command set into generate/build/sim rungs."""
    spec = state.get("workload_spec", {})
    isa_spec = state.get("isa_spec", {}) or {}
    overlay = agent_cfu_overlay_commands(state, isa_spec)
    if overlay:
        return {
            "generate": overlay,
            "build": [],
            "sim": agent_cfu_sim_commands(state, isa_spec),
        }
    commands, _errors = validation_commands_for_spec(spec, state.get("task", ""), toolbox)
    generate = [c for c in commands if "MiCoSocGen" in " ".join(c)]
    sim = [c for c in commands if "MiCoSocSim" in " ".join(c)]
    build = [c for c in commands if c not in generate and c not in sim]
    return {"generate": generate, "build": build, "sim": sim}


def _software_build_commands(state: CfuDesignState, toolbox: RepoToolbox) -> list[list[str]]:
    project = state.get("benchmark_project", {})
    spec = state.get("workload_spec", {})
    run_root = state.get("run_root", "")
    if str(project.get("kind", "")) == "embench_benchmark":
        name = str(project.get("benchmark", "") or spec.get("benchmark_name", ""))
        return [embench.build_command(run_root, name, "cfu")] if name else []
    commands: list[list[str]] = []
    for key in ("build_cmd", "test_cmd"):
        raw = str(project.get(key, "")).strip()
        if raw:
            commands.append(shlex.split(raw))
    if commands:
        return commands
    return _legacy_ladder_commands(state, toolbox)["build"]


def _isolated_software_check_commands(
    state: CfuDesignState, toolbox: RepoToolbox
) -> list[list[str]]:
    """Graph-owned SW compile argv with cache/output paths isolated from final Gate."""
    commands = _software_build_commands(state, toolbox)
    isolated: list[list[str]] = []
    run_root = state.get("run_root", "")
    for argv in commands:
        rewritten: list[str] = []
        for token in argv:
            if token.startswith("BUILD="):
                rewritten.append(f"BUILD=../{run_root}/workspace/checks/sw/build")
            else:
                rewritten.append(token)
        # Generic commands without an explicit BUILD cannot be safely isolated;
        # do not expose them through the coding tool pilot.
        if any(token.startswith("BUILD=") for token in argv):
            isolated.append(rewritten)
    return isolated


def _software_sim_commands(state: CfuDesignState, toolbox: RepoToolbox) -> list[list[str]]:
    project = state.get("benchmark_project", {})
    spec = state.get("workload_spec", {})
    run_root = state.get("run_root", "")
    isa_spec = state.get("isa_spec", {}) or {}
    if str(project.get("kind", "")) == "embench_benchmark":
        name = str(project.get("benchmark", "") or spec.get("benchmark_name", ""))
        if not name:
            return []
        return agent_cfu_sim_commands(state, isa_spec, elf=embench.elf_path(run_root, name, "cfu"))
    overlay_sim = agent_cfu_sim_commands(state, isa_spec)
    if overlay_sim:
        return overlay_sim
    raw = str(project.get("run_cmd", "")).strip()
    if raw:
        return [shlex.split(raw)]
    return _legacy_ladder_commands(state, toolbox)["sim"]


CONFORMANCE_SUBDIR = "09_implementation/conformance"


CONFORMANCE_SOURCE = "cfu_conformance.c"


CONFORMANCE_BIN = "cfu_conformance"


def _conformance_workspace(state: CfuDesignState) -> str:
    return f"{state.get('run_root', '')}/{CONFORMANCE_SUBDIR}"


def _conformance_scalar_benchmark(state: CfuDesignState) -> tuple[str, str]:
    """(benchmark name, reference tree) for an Embench workload, else ("", "")."""
    project = state.get("benchmark_project") or {}
    name = str(project.get("benchmark") or "").strip()
    run_root = str(state.get("run_root") or "").strip()
    if not name or not run_root:
        return "", ""
    return name, embench.config_workspace(run_root, name, "reference")


def conformance_scalar_sources(state: CfuDesignState) -> list[str]:
    """Every workload scalar source the oracle may `#include`, repo-relative.

    Verified end to end: the real build command links a conformance test that
    includes ``beebsc.c`` and ``md5.c`` of the pristine reference tree
    (``-ffunction-sections`` + ``--gc-sections`` drops ``benchmark_body``, so the
    run's own ``main`` stays the only entry point).

    A CFU's semantics are a transcription of the workload's scalar code, so the
    conformance oracle may `#include` that code instead of copying its constant
    tables by hand: run 20261005-073745 hand-copied md5.c's 64-entry K table,
    dropped one entry, and the rung then failed *correct* hardware for three
    consecutive rounds. Only the ``reference`` configuration is offered — the
    harness-owned plain build that `embench.workspace_tampering` guards, never the
    writable ``cfu`` copy whose CFU branch would make the test self-referential.
    ``support/beebsc.c`` comes along because the Embench scalar sources allocate
    their scratch message on the Beebs bump allocator; ``support/main.c`` is
    deliberately excluded (it defines ``main``).
    """
    name, root = _conformance_scalar_benchmark(state)
    if not name:
        return []
    workdir = Path(str(state.get("workdir") or "."))
    sources = embench.config_sources(
        workdir, str(state.get("run_root") or "").strip(), name, "reference")
    if not sources:
        return []
    allocator = f"{root}/support/beebsc.c"
    if (workdir / allocator).is_file():
        sources.append(allocator)
    return sources


def _scalar_reference_root(state: CfuDesignState) -> str:
    """The reference tree when it is actually present on disk, else ""."""
    _name, root = _conformance_scalar_benchmark(state)
    if not root:
        return ""
    return root if (Path(str(state.get("workdir") or ".")) / root).is_dir() else ""


def conformance_scalar_includes(state: CfuDesignState) -> list[str]:
    """Include dirs of that scalar tree, repo-relative (empty when unavailable)."""
    root = _scalar_reference_root(state)
    return [f"{root}/src", f"{root}/support", f"{root}/board"] if root else []


def conformance_scalar_defines(state: CfuDesignState) -> list[str]:
    """The benchmark's own defines, which its scalar source needs to compile.

    ``md5.c`` only builds with the Embench ``-D`` set (``GLOBAL_SCALE_FACTOR`` and
    friends). They are the same harness-owned defines ``embench.build_command``
    passes for the reference configuration, so including the scalar source adds no
    flag the benchmark build does not already use.
    """
    name, _root = _conformance_scalar_benchmark(state)
    return embench.config_defines(name, "reference") if name and _scalar_reference_root(state) else []


def _conformance_syntax_command(state: CfuDesignState, header_path: str) -> list[str]:
    """Check the harness-owned C without assembling, linking or running it.

    All paths are relative to the repository workdir, unlike the ``make -C sw``
    build below. The compiler and target flags are fixed: workload commands and
    ISA metadata must not turn this implementation preflight into a build.
    """
    if not str(header_path or "").strip():
        raise ValueError("conformance syntax check requires an intrinsics header path")
    includes = ["-I", str(Path(header_path).parent), "-I", "sw/MiCo-Lib/targets/vexii_soc"]
    scalar_dirs = conformance_scalar_includes(state)
    for directory in scalar_dirs:
        includes.extend(["-I", directory])
    scalar_defines = conformance_scalar_defines(state)
    includes.extend(scalar_defines)
    # Embench scalar files may use pre-C23 `typedef uint8_t bool`; compile them
    # under the same GNU C11 mode as reference/profile/CFU builds. Other oracle
    # syntax checks keep their existing GNU C mode.
    c_standard = embench.DEFAULT_C_STANDARD if scalar_dirs else "-std=gnu99"
    return [
        "riscv64-unknown-elf-gcc",
        "-fsyntax-only",
        # GNU C is required because generated intrinsics bind operand registers
        # with `register uint32_t r1 asm(\"a1\")`.
        c_standard,
        "-Werror=implicit-function-declaration",
        "-march=rv32imc_zicsr_zifencei",
        "-mabi=ilp32",
        *includes,
        f"{_conformance_workspace(state)}/{CONFORMANCE_SOURCE}",
    ]


def _conformance_build_command(state: CfuDesignState, header_path: str) -> tuple[list[str], str]:
    """make invocation that builds the harness-owned micro-test, plus its ELF.

    Mirrors ``embench.build_command``: paths are relative to ``sw/`` because the
    Makefile is invoked with ``-C sw``. The test is the ``MAIN`` translation unit,
    so it must NOT also appear in ``EXTRA_SOURCES`` (the Makefile links
    ``$(OBJS) $(MAIN).c``, and listing it twice is a duplicate ``main``).
    ``vexii_soc.mk`` already links ``start.S``/``soc_stdio.c``, so the test needs
    no board support sources.
    """
    cfg = _conformance_workspace(state)
    rel = os.path.relpath(cfg, "sw")
    header_dir = os.path.relpath(os.path.dirname(header_path) or ".", "sw")
    # The oracle may `#include` the workload's pristine scalar source (see
    # `conformance_scalar_sources`), so the reference tree joins the include path.
    include_dirs = [header_dir, *(
        os.path.relpath(directory, "sw") for directory in conformance_scalar_includes(state)
    )]
    scalar_defines = conformance_scalar_defines(state)
    defines = " ".join([embench.DEFAULT_C_STANDARD, *scalar_defines]) if scalar_defines else ""
    elf = f"{cfg}/{CONFORMANCE_BIN}.elf"
    return (
        [
            "make",
            "-C",
            "sw",
            "TARGET=vexii_soc",
            f"MARCH={DEFAULT_MARCH}",
            f"MAIN={rel}/{CONFORMANCE_BIN}",
            f"BUILD={rel}/build",
            f"EXTRA_INCLUDES={' '.join(include_dirs)}",
            *([f"EXTRA_CFLAGS={defines}"] if defines else []),
            "compile",
        ],
        elf,
    )


def _software_elf(state: CfuDesignState) -> str:
    project = state.get("benchmark_project", {})
    spec = state.get("workload_spec", {})
    run_root = state.get("run_root", "")
    if str(project.get("kind", "")) == "embench_benchmark":
        name = str(project.get("benchmark", "") or spec.get("benchmark_name", ""))
        return embench.elf_path(run_root, name, "cfu") if name else ""
    return str(project.get("elf_path", "") or "")


def agent_cfu_overlay_commands(state: CfuDesignState, spec: dict) -> list[list[str]]:
    """Build the SoC generation command that overlays the run workspace design.

    The tracked AgentCfu*.scala scaffolds are excluded and the workspace copies
    are compiled in their place, so an agent-designed CFU reaches the generated
    hardware without any repo file changing.
    """
    if not gates.is_agent_cfu_run(state):
        return []
    settings = agent_cfu_overlay_settings(state)
    if not settings:
        return []
    # MiCoSocGen writes MiCoSoc.v/soc.h into the process working directory, so
    # the forked run is pointed at the run workspace to keep the repo clean.
    set_out_dir = (
        "set run / baseDirectory := (Compile/baseDirectory).value / "
        f'"{state.get("run_root", "")}/{SOC_WORKSPACE_SUBDIR}"'
    )
    flags = agent_cfu_gen_flags(spec, state.get("target_frequency_mhz"))
    # sbt takes each command as one argv element, so the subcommand and its
    # flags are joined into a single element.
    run_main = " ".join(["runMain vexiiriscv.soc.mico.MiCoSocGen", *flags])
    return [["sbt", *settings, set_out_dir, run_main]]


def agent_cfu_overlay_settings(state: CfuDesignState) -> list[str]:
    """sbt settings that compile the run workspace CFU over the tracked scaffold."""
    run_root = state.get("run_root", "")
    if not run_root or not gates.is_agent_cfu_run(state):
        return []
    design_dir = f"{run_root}/{DESIGN_WORKSPACE_SUBDIR}"
    # Add the workspace design dir and drop the tracked scaffolds from the
    # resolved source list. AgentCfuSourceFilter lives in project/ and keeps the
    # logic metacharacter-free, so the command policy check stays meaningful.
    add_overlay = (
        "set Compile/unmanagedSourceDirectories += "
        f'(Compile/baseDirectory).value / "{design_dir}"'
    )
    swap_sources = (
        "set Compile/unmanagedSources := "
        "AgentCfuSourceFilter.sources((Compile/unmanagedSourceDirectories).value)"
    )
    return [add_overlay, swap_sources]


def _agent_cfu_check_out_dir(state: CfuDesignState, check_index: int = 0) -> str:
    run_root = state.get("run_root", "")
    attempt = int((state.get("attempts") or {}).get("implement_hw", 0) or 0)
    return f"{run_root}/workspace/checks/hw/attempt_{attempt:03d}/check_{check_index:03d}/cfu_rtl"


def agent_cfu_check_commands(state: CfuDesignState, check_index: int = 0) -> list[list[str]]:
    """Isolated standalone elaboration used only inside the hardware coding loop."""
    run_root = state.get("run_root", "")
    if not run_root or not gates.is_agent_cfu_run(state):
        return []
    settings = agent_cfu_overlay_settings(state)
    if not settings:
        return []
    out_dir = _agent_cfu_check_out_dir(state, check_index)
    flags = agent_cfu_datapath_flags(state.get("isa_spec", {}) or {})
    run_main = " ".join(
        ["runMain vexiiriscv.soc.mico.GenAgentCfu", "--out-dir", out_dir, *flags]
    )
    return [["sbt", *settings, run_main]]


def agent_cfu_cost_commands(state: CfuDesignState) -> list[list[str]]:
    """sbt command that elaborates the standalone CFU Verilog for the cost rung.

    Unlike the SoC build this does not need the CPU: GenAgentCfu elaborates only
    the overlaid AgentCfu class, so Yosys can synthesize the CFU in isolation.

    The AgentCfu configuration comes from the state's ISA spec -- the SAME
    source ``agent_cfu_gen_flags`` uses for the SoC build and the simulation.
    The cost rung must elaborate the exact configuration that was built and
    simulated, or a design's parameter checks fail here after passing everywhere
    else (observed 2026-09-28: this function took the WORKLOAD spec, emitted no
    datapath flags at all, and GenAgentCfu fell back to vlen=256 against a
    design that required 512).
    """
    run_root = state.get("run_root", "")
    if not run_root or not gates.is_agent_cfu_run(state):
        return []
    settings = agent_cfu_overlay_settings(state)
    if not settings:
        return []
    isa_spec = state.get("isa_spec", {}) or {}
    out_dir = f"{run_root}/11_cost/cfu_rtl"
    flags = agent_cfu_datapath_flags(isa_spec)
    run_main = " ".join(
        ["runMain vexiiriscv.soc.mico.GenAgentCfu", "--out-dir", out_dir, *flags]
    )
    return [["sbt", *settings, run_main]]


def agent_cfu_sim_commands(
    state: CfuDesignState,
    spec: dict,
    elf: str = "",
) -> list[list[str]]:
    """Simulation command for the overlaid agent design, when an ELF is known."""
    elf = str(elf or state.get("benchmark_project", {}).get("elf_path", "") or "")
    if not elf:
        return []
    run_root = state.get("run_root", "")
    if not run_root:
        return []
    design_dir = f"{run_root}/{DESIGN_WORKSPACE_SUBDIR}"
    add_overlay = (
        "set Compile/unmanagedSourceDirectories += "
        f'(Compile/baseDirectory).value / "{design_dir}"'
    )
    swap_sources = (
        "set Compile/unmanagedSources := "
        "AgentCfuSourceFilter.sources((Compile/unmanagedSourceDirectories).value)"
    )
    flags = agent_cfu_gen_flags(spec, state.get("target_frequency_mhz"))
    run_main = " ".join(
        ["runMain vexiiriscv.soc.mico.MiCoSocSim", "--load-elf", elf, *flags]
    )
    return [["sbt", add_overlay, swap_sources, run_main]]


def agent_cfu_datapath_flags(spec: dict) -> list[str]:
    """AgentCfu generation flags (datapath + memory options) from the ISA spec.

    SINGLE SOURCE OF TRUTH for the AgentCfu configuration: the SoC build, the
    simulation and the cost rung's standalone GenAgentCfu all derive their
    flags here, so the CFU that Yosys measures is bit-identical in
    configuration to the CFU that was built and simulated.
    """
    datapath = spec.get("datapath", {}) if isinstance(spec.get("datapath"), dict) else {}
    memory = spec.get("memory", {}) if isinstance(spec.get("memory"), dict) else {}
    flags: list[str] = []
    vlen = datapath.get("vlen")
    xlen = datapath.get("xlen")
    reg_depth = datapath.get("regDepth")
    if isinstance(vlen, int) and vlen > 0:
        flags += ["--agent-cfu-vlen", str(vlen)]
    if isinstance(xlen, int) and xlen > 0:
        flags += ["--agent-cfu-bus-width", str(xlen)]
    if isinstance(reg_depth, int) and reg_depth > 0:
        flags += ["--agent-cfu-reg-depth", str(reg_depth)]
    # Memory options map 1:1 onto AgentCfuParameter's withLoad/withStore/withTilelink.
    # Forwarding them keeps every rung on the same configuration; dropping them
    # silently rebuilt a CFU with load/store hardware the contract had disabled.
    load = memory.get("load")
    store = memory.get("store")
    if load is False:
        flags += ["--agent-cfu-no-load"]
    if store is False:
        flags += ["--agent-cfu-no-store"]
    if load is False and store is False:
        flags += ["--agent-cfu-no-tilelink"]
    return flags


def agent_cfu_gen_flags(spec: dict, frequency_mhz: float | None = None) -> list[str]:
    """CLI flags for an agent-CFU SoC build, derived from the ISA datapath."""
    frequency = []
    if frequency_mhz is not None:
        import math
        value = float(frequency_mhz)
        if not math.isfinite(value) or not 0 < value <= 1000:
            raise ValueError("target frequency must be finite and between 0 and 1000 MHz")
        frequency = ["--system-frequency", str(round(value * 1_000_000))]
    return [
        *frequency,
        "--with-rvc",
        "--with-rvm",
        "--with-rdtime",
        "--mico-agent-cfu",
        *agent_cfu_datapath_flags(spec),
    ]


def validation_commands_for_spec(spec: dict, task: str, toolbox: RepoToolbox | None = None) -> tuple[list[list[str]], list[str]]:
    project_commands, errors = project_validation_commands(spec, toolbox)
    if project_commands:
        return project_commands, errors

    operation = str(spec.get("operation", "")).lower()
    lowered = f"{task.lower()} {operation}"
    common = "--with-rvc --with-rvm --with-rdtime"
    if "simd8" in lowered or ("sum" in lowered and "weighted" not in lowered):
        flag = "--mico-simd8-sum-cfu"
        elf = "sw/tests/simd8_sum_cfu_test.elf"
    elif "vadd" in lowered or ("element" in lowered and "add" in lowered):
        flag = "--mico-i8-vadd-cfu"
        elf = "sw/tests/i8_vadd_cfu_test.elf"
    else:
        flag = "--mico-u8-wavg-cfu"
        elf = "sw/tests/u8_wavg_cfu_test.elf"
    return [
        ["sbt", f"runMain vexiiriscv.soc.mico.MiCoSocGen {common} {flag}"],
        ["sbt", f"runMain vexiiriscv.soc.mico.MiCoSocSim --load-elf {elf} {common} {flag}"],
    ], errors


def project_validation_commands(spec: dict, toolbox: RepoToolbox | None) -> tuple[list[list[str]], list[str]]:
    commands: list[list[str]] = []
    errors: list[str] = []
    if spec.get("source_kind") != "c_project":
        return commands, errors
    for key in ("build_cmd", "test_cmd", "run_cmd"):
        raw = str(spec.get(key, "")).strip()
        if not raw:
            continue
        try:
            args = shlex.split(raw)
        except ValueError as exc:
            errors.append(f"{key} could not be parsed: {exc}")
            continue
        if toolbox is not None and not toolbox.command_allowed(args):
            errors.append(f"{key} is not allowlisted and was skipped: {raw}")
            continue
        commands.append(args)
    return commands, errors


def cost_top_for_spec(spec: dict, task: str, *, agent_cfu: bool = False) -> str:
    if agent_cfu:
        return "AgentCfu"
    operation = str(spec.get("operation", "")).lower()
    lowered = f"{task.lower()} {operation}"
    if "simd8" in lowered or ("sum" in lowered and "weighted" not in lowered):
        return "Simd8SumCfu"
    if "vadd" in lowered or ("element" in lowered and "add" in lowered):
        return "I8VAddCfu"
    return "U8WeightedAvgCfu"


def cost_case_for_spec(spec: dict, task: str, *, agent_cfu: bool = False) -> str:
    return cost_top_for_spec(spec, task, agent_cfu=agent_cfu).replace("Cfu", "_cfu").lower()
